import{_ as i,o as r,c as o,ah as t}from"./chunks/framework.DjU4PSOm.js";const b=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"파트 1: 현상학의 기획과 시대 비판","slug":"파트-1-현상학의-기획과-시대-비판","link":"#파트-1-현상학의-기획과-시대-비판","children":[]},{"level":2,"title":"파트 2: 기본 개념 및 환원","slug":"파트-2-기본-개념-및-환원","link":"#파트-2-기본-개념-및-환원","children":[]},{"level":2,"title":"파트 3: 지각의 구조","slug":"파트-3-지각의-구조","link":"#파트-3-지각의-구조","children":[]},{"level":2,"title":"파트 4: 판단과 인식 단계","slug":"파트-4-판단과-인식-단계","link":"#파트-4-판단과-인식-단계","children":[]},{"level":2,"title":"파트 5: 의식의 심층과 시간","slug":"파트-5-의식의-심층과-시간","link":"#파트-5-의식의-심층과-시간","children":[]}],"relativePath":"philosophy/Phenomenology/08. 중간고사 Q&A.md","filePath":"philosophy/Phenomenology/08. 중간고사 Q&A.md"}'),n={name:"philosophy/Phenomenology/08. 중간고사 Q&A.md"};function s(e,l,p,a,g,u){return r(),o("div",null,[...l[0]||(l[0]=[t('<blockquote><p>중간고사(후설 파트) 자가 테스트용 문답. 질문 → 답 순서로 정리.</p></blockquote><h2 id="파트-1-현상학의-기획과-시대-비판" tabindex="-1">파트 1: 현상학의 기획과 시대 비판 <a class="header-anchor" href="#파트-1-현상학의-기획과-시대-비판" aria-label="Permalink to &quot;파트 1: 현상학의 기획과 시대 비판&quot;">​</a></h2><p><strong>1. 당시 학문 비판, 구별점</strong></p><ol><li>독일 관념론 <ul><li>사변적이다. 인식을 세계 근거로까지 확장하였다.</li><li>자연주의와 역사주의에 동기를 불어넣음 — 사변적 동기 반발, 상대주의적 경향</li><li>의식을 세계의 근원으로 본 것이 아니라 인식의 근원으로만 보았음</li></ul></li><li>자연주의 <ul><li>자연과학으로 설명되지 않는 것을 무리하게 포섭하려 함</li><li>어떤 논리체계로 환원되는 자연과학체계가 없어지더라도 그 논리체계는 여전히 참</li><li>의식에 대한 탐구만 정당하다는 것이 아니라, 그것이 학문의 토대를 제공함</li></ul></li><li>역사주의 <ul><li>학문의 객관성을 상실하게 함</li><li>피타고라스 정리를 발견한 역사적 배경이 피타고라스 정리를 정당화해주지 않음</li><li>진리가 의식에 상대적이라는 것이 아니라, 그 구조와 방식을 탐구해야 함</li></ul></li></ol><h2 id="파트-2-기본-개념-및-환원" tabindex="-1">파트 2: 기본 개념 및 환원 <a class="header-anchor" href="#파트-2-기본-개념-및-환원" aria-label="Permalink to &quot;파트 2: 기본 개념 및 환원&quot;">​</a></h2><p><strong>1. 현상학적 환원 3가지 설명</strong><br> 세계에서 현상으로 눈을 돌리는 것</p><ol><li>데카르트적 환원: 확실하지 않은 것에서 확실한 것으로 눈을 돌림</li><li>심리학적 환원: 심리학적 개념인 생물학적, 시공간적 요소에서 벗어나 남는 것으로 눈을 돌림</li><li>생활세계적 환원: 선학문적 세계에서 생활세계로 눈을 돌림</li></ol><p><strong>2. &#39;형상적 환원&#39;</strong><br> 속성에서 벗어나 대상의 형상(본질)에 주목</p><p><strong>3. &#39;직관&#39;이란</strong><br> 대상을 느끼거나 경험하는 것</p><p><strong>4. 직관의 4가지 종류</strong><br> 지각, 회상, 예상, 상상</p><ul><li>지각: 대상이 현재 있는 것으로 느껴지는 것 / 직접적 명증</li><li>회상: 대상이 어딘가에 있는 것으로 느껴지는 것 / 간접적 명증</li><li>예상: 대상이 언젠가 있을 것으로 느껴지는 것</li><li>상상: 대상이 지금 없는 것으로 느껴지는 것 / 명증적이지 않음</li></ul><p><strong>5. &#39;명증&#39;이란</strong><br> 정립에 대한 정당성 또는 정당화</p><p><strong>6. &#39;반성&#39;이란</strong><br> 스스로의 의식에 대한 직접적 탐구</p><p><strong>7. 지향</strong> (충족, 기대, 실망)<br> 지향: 어떤 대상에 대한 것. 어떠한 직관이 느껴질 것이라는 기대. 경험이 기대와 일치하면 충족, 다르면 실망. 실망은 최소한의 충족을 가지고 이뤄짐.</p><h2 id="파트-3-지각의-구조" tabindex="-1">파트 3: 지각의 구조 <a class="header-anchor" href="#파트-3-지각의-구조" aria-label="Permalink to &quot;파트 3: 지각의 구조&quot;">​</a></h2><p><strong>1. 지각 의미 2개</strong><br> 넓은 의미에서는 대상을 직접적으로 느끼거나 관찰. 좁은 의미에서는 사물을 직접적으로 느끼거나 관찰.</p><p><strong>2. 작용</strong><br> 어떠한 지향성을 가지는 의식</p><p><strong>3. 파악</strong><br> 어떤 경험을 통해 새로운 것으로 인식하는 것</p><p><strong>4. 지평</strong><br> 어떤 대상을 인식할 때 암묵적으로 동시에 인식되는 것들</p><p><strong>5. &#39;내적 지평&#39;과 &#39;외적 지평&#39;의 차이는 무엇인가요?</strong><br> 대상의 부분과 대상 내적 속성, 대상의 환경과 대상 외적인 속성</p><p><strong>6. &#39;고유감각&#39;이란?</strong><br> 몸의 내부에 대한 감각</p><p><strong>7. 지각의 구조 3단계 설명</strong><br> 시간 구조, 공간 구조, 인과 구조</p><ul><li>시간 구조 - 지속: 순간적 감각적 성질이 지속적 감각적 성질으로 변화</li><li>공간 구조 - 환영: 지속적 인상이 공간적 형태로 변화</li><li>인과 구조 - 사물: 공간적 형태가 인과적 실체로 변화</li></ul><p><strong>8. 지각이 &#39;직접적 명증&#39;을 갖는다는 것은 어떤 의미인가?</strong><br> 어떠한 추론이나 믿음 없이 대상이 실제로 존재한다는 것을 의식 속에서 직접적으로 정당화</p><h2 id="파트-4-판단과-인식-단계" tabindex="-1">파트 4: 판단과 인식 단계 <a class="header-anchor" href="#파트-4-판단과-인식-단계" aria-label="Permalink to &quot;파트 4: 판단과 인식 단계&quot;">​</a></h2><p><strong>1. 판단과 감각적 경험의 관계</strong><br> 판단이란 사실, 추상적 대상에 대한 인식. 사태, &quot;A가 ~한 상태에 있다.&quot; 감각적 경험이 판단의 근원.</p><p><strong>2. 추상적 대상, 종류 3개</strong><br> 사실, 집합, 보편자</p><p><strong>3. 사실 인식 과정</strong></p><ul><li>전체와 부분의 종합: 전체의 경험과 부분에 대한 경험이 합치함</li><li>명시화: 전체에 주목하면서 부분에 주목함</li><li>사실 인식: x가 P라는 사실, 전체와 부분을 기체-속성 구조로 파악</li></ul><p><strong>4. 집합 인식 과정</strong></p><ul><li>연언의 종합: 유사한 속성이 있는 대상들을 동시에 주목함</li><li>집합 인식: 그러한 대상들을 하나의 집합으로 인식</li></ul><p><strong>5. 보편자 인식 과정</strong></p><ul><li>유사한 대상들의 종합: 유사한 대상들에 대한 경험이 합치함</li><li>개별적 성질 파악: 대상들 각각에 대해 그것이 P라고 판단함</li><li>보편자 인식: 보편적 인식 P를 인식함</li></ul><h2 id="파트-5-의식의-심층과-시간" tabindex="-1">파트 5: 의식의 심층과 시간 <a class="header-anchor" href="#파트-5-의식의-심층과-시간" aria-label="Permalink to &quot;파트 5: 의식의 심층과 시간&quot;">​</a></h2><p><strong>1. 현상학적 시간</strong><br> 대상이 현재, 과거, 미래의 것으로 의식되는 방식</p><p><strong>2. 촉발</strong><br> 대상이 주체를 자극하여 어떠한 행동을 일으키는 것</p><p><strong>3. 현상학적 시간의 각각 3가지 요소</strong></p><ul><li>일상적인 현상학적 시간: 지각, 회상, 예상</li><li>근원적인 현상학적 시간: 인상, 파지, 예지 <ul><li>인상: 자료들이 지금 경험됨</li><li>파지: 방금 경험된 자료들이 여전히 의식됨</li><li>예지: 아직 경험되지 않은 자료들이 의식됨</li></ul></li></ul><p><strong>4. 내적 의식, 외적 의식</strong></p><ul><li>내적 의식: 의식에 관한 의식</li><li>외적 의식: 의식 바깥의 대상에 관한 의식</li><li>반성은 외적 의식을 전제함</li><li>근원적 내적의식이 자료와 작용을 의식하고, 작용이 자료를 의식 바깥의 대상들로 파악</li></ul><p><strong>5. 촉발의 방식 두 가지 (융합, 대조)</strong></p><ul><li>융합: 질적으로 같은 자료들이 서로 합쳐지고 촉발을 일으킴</li><li>대조: 질적으로 다른 자료들이 서로 분리되고 촉발을 일으킴</li></ul><p><strong>6. &#39;파지(Retention)&#39;가 &#39;회상&#39;과 다른 점</strong><br> 파지는 지나간 과거를 의식 속에 붙잡고 있는 것(수동적), 회상은 완전히 사라진 과거를 의식 속에 다시 불러일으키는 것(능동적)</p><p><strong>7. 왜 &#39;파지&#39;와 &#39;예지&#39;는 직관이 아닌가</strong><br> 파지와 예지가 직관이라면 그것이 인상과 동시에 함께 음이 들려야 하지만 그렇지 않기 때문에 직관이 아니다</p>',44)])])}const d=i(n,[["render",s]]);export{b as __pageData,d as default};
